-- =============================================================================
-- CreatiVue Supabase DB 시드 데이터 (100개 프로젝트 - 전체 지원자 분배 강화 버전)
-- =============================================================================

TRUNCATE public.project_submissions CASCADE;
TRUNCATE public.project_applicants CASCADE;
TRUNCATE public.projects CASCADE;
TRUNCATE public.brands CASCADE;
TRUNCATE public.freelancers CASCADE;
TRUNCATE public.clients CASCADE;
TRUNCATE public.user_profiles CASCADE;
TRUNCATE public.banner CASCADE;

-- RLS (Row Level Security) 공공 조회(SELECT) 정책 보장
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select projects" ON public.projects;
CREATE POLICY "Allow public select projects" ON public.projects FOR SELECT USING (true);

ALTER TABLE public.brands ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select brands" ON public.brands;
CREATE POLICY "Allow public select brands" ON public.brands FOR SELECT USING (true);

ALTER TABLE public.project_applicants ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select project_applicants" ON public.project_applicants;
CREATE POLICY "Allow public select project_applicants" ON public.project_applicants FOR SELECT USING (true);

ALTER TABLE public.banner ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select banner" ON public.banner;
CREATE POLICY "Allow public select banner" ON public.banner FOR SELECT USING (true);

-- 기존 전용 시드 계정 정화
DELETE FROM auth.users WHERE email LIKE 'seed_%@creativue.internal';

