-- 8. banner 시딩
INSERT INTO public.banner (id, badge_text, main_title, sub_title, description, image, sort_order)
VALUES
  (1, 'Problem 01', '주관적 시각', '대표자의 눈에 예쁜 포스터가 정답?', '브랜드 전략 없이 대표자 개인의 취향으로 디자인을 선택하면, 정작 소비자에게는 전혀 다른 메시지가 전달됩니다.', 'https://images.unsplash.com/photo-1590102426275-8d1c367070d3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080', 1),
  (2, 'Problem 02', '불명확한 브랜드 정의', '자사 브랜드를 모른 채 마케팅 시작', '브랜드 아이덴티티 없이 프리랜서 평점만 보고 의뢰하면 매번 다른 결과물이 나옵니다. 일관성 있는 브랜드를 만들 수 없어요.', 'https://images.unsplash.com/photo-1684326156737-4755d6d03524?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080', 2),
  (3, 'Problem 03', '브랜딩 = 로고?', '로고 하나로 마케팅을 시작하는 함정', '로고는 브랜딩의 시작일 뿐입니다. 색상 체계, 톤앤매너, 타겟 페르소나 없이는 로고조차 제 역할을 못합니다.', 'https://images.unsplash.com/photo-1776015036380-4022fe844ed8?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080', 3),
  (4, 'Problem 04', '불명확한 타게팅', '"누구에게 팔고 싶으세요?" → 침묵', '타겟 고객을 명확히 정의하지 못하면 어떤 마케팅도 효과를 내기 어렵습니다. 모두를 타겟으로 삼으면 아무도 잡을 수 없습니다.', 'https://images.unsplash.com/photo-1774921676744-4c4133c44bf0?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080', 4),
  (5, 'Problem 05', '해외 시장의 장벽', '현지 정서를 모르는 글로벌 콘텐츠', '해외 소비자를 대상으로 한 콘텐츠에 정서적·문화적·언어적 오류가 있으면 브랜드 이미지가 심각하게 손상될 수 있습니다.', 'https://images.unsplash.com/photo-1767449441925-737379bc2c4d?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080', 5)
ON CONFLICT (id) DO NOTHING;
